import{c as t,Q as l,j as e,m as i}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"REGIST_MATMUL_OBJ","description":"","frontmatter":{},"headers":[{"level":1,"title":"REGIST\\\\_MATMUL\\\\_OBJ","slug":"regist_matmul_obj"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/REGIST_MATMUL_OBJ.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/REGIST_MATMUL_OBJ.md"}'),n={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/REGIST_MATMUL_OBJ.md"};function s(p,a,r,m,o,d){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="regist-matmul-obj" tabindex="-1">REGIST_MATMUL_OBJ <a class="header-anchor" href="#regist-matmul-obj" aria-label="Permalink to &quot;REGIST\\_MATMUL\\_OBJ&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>初始化Matmul对象。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(tpipe, workspace, ...)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>tpipe</td><td>输入</td><td>Tpipe对象。</td></tr><tr><td>workspace</td><td>输入</td><td>系统workspace指针。</td></tr><tr><td>...</td><td>输入</td><td>可变参数，传入Matmul对象和与之对应的Tiling结构，要求Tiling结构的数据类型为TCubeTiling结构。 Tiling参数可以通过Host侧GetTiling接口获取，并传递到kernel侧使用。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>在分离模式中，本接口必须在<a href="./../../../基础API/资源管理/Pipe和Que框架/TPipe/InitBuffer.html">InitBuffer</a>接口前调用。</li><li>在程序中，最多支持定义4个Matmul对象。</li><li>在Matmul的内部实现中使用了<a href="./../../../基础API/同步控制/核间同步/CrossCoreSetFlag(ISASI).html">CrossCoreSetFlag</a>进行核间同步控制，因此不建议开发者同时使用CrossCoreSetFlag和Matmul，以避免核间同步标记flagId冲突的风险。Matmul高阶API内部占用的flagId范围与定义的Matmul对象数目相关。假设定义了N个Matmul对象，则Matmul高阶API内部占用的flagId范围为[0, 2 * N - 1]。Matmul最多支持定义4个对象，此时flagId占用范围为[0, 7]。</li><li>当代码中只有一个Matmul对象时，本接口可以不传入tiling参数，通过<a href="./Init-85.html">Init</a>接口单独传入tiling参数。</li><li>当代码中有多个Matmul对象时，必须满足Matmul对象与其tiling参数一一对应，依次传入，具体方式请参考调用示例。</li><li>在分离模式中，调用本接口后，AIC核不会主动执行接口，仅在AIV核执行到下述接口后，才会触发AIC核的执行，其他接口则不会在AIC核上执行。 <ul><li><a href="./Matmul-Kernel侧接口.html">Matmul Kernel侧接口</a>。</li><li><a href="./../../../基础API/Memory数据搬运/DataCopy/基础数据搬运.html">基础数据搬运</a>和<a href="./../../../基础API/Memory数据搬运/DataCopy/随路转换ND2NZ搬运.html">随路转换ND2NZ搬运</a>接口，仅支持数据通路为GM -&gt; A1、B1的数据搬运。</li></ul></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tpipe pipe;</span></span>
<span class="line"><span>// 推荐：初始化单个matmul对象，传入tiling参数</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>// 推荐：初始化多个matmul对象，传入对应的tiling参数</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1, mm1tiling, mm2, mm2tiling, mm3, mm3tiling, mm4, mm4tiling);</span></span>
<span class="line"><span>// 初始化单个matmul对象，未传入tiling参数。注意，该场景下需要使用Init接口单独传入tiling参数。这种方式将matmul对象的初始化和tiling的设置分离，比如，Tiling可变的场景，可通过这种方式多次对Tiling进行重新设置</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span>mm.Init(&amp;tiling);</span></span></code></pre></div>`,14)])])}const c=t(n,[["render",s]]);export{u as __pageData,c as default};
